import{_ as n,o as e,c as s,aj as t}from"./chunks/framework.BdtAaXf2.js";const o="/assets/image-20260706222111692.BWfqileu.png",i="/assets/image-20260706222213006.BL0dpGO7.png",p="/assets/image-20260706222305619.BdyFRpRg.png",d="/assets/image-20260706222638079.CDpkuvrZ.png",m="/assets/image-20260706222733246.C-Tc8DCa.png",r="/assets/image-20260706222801051.BusMBLG2.png",l="/assets/image-20260706222956780.BubDAOpP.png",c="/assets/image-20260706223601227.DTMAo1pj.png",g="/assets/image-20260706223701770.jyWUhw2V.png",h="/assets/image-20260706223758410.hF9G7EXU.png",u="/assets/image-20260706223942865.BXQ5RlqU.png",b="/assets/image-20260706224235790.GizMUwt0.png",C="/assets/image-20260706224318689.DPxGSc8j.png",_="/assets/image-20260706224339445.DX0Kicrb.png",A="/assets/image-20260706224552181.D2YSWD3h.png",v="/assets/image-20260706224614075.Bcemg6bw.png",D=JSON.parse('{"title":"AtomCode 解读任意开源工程","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/AtomCode 解读任意开源工程/AtomCode 解读任意开源工程.md","filePath":"AI人工智能/AtomCode 解读任意开源工程/AtomCode 解读任意开源工程.md","lastUpdated":1783350445000,"__rawMarkdown":"# AtomCode 解读任意开源工程\\n\\n## 前言\\n\\n在学习技术的过程中，开源工程是必不可少的学习资料，但是对于一个可能几十、几百甚至几千个文件来说，学习者可能会一头雾水，不知道应该从何学起，这里讲解如何使用AtomCode来打造一个源码解读工具，掌握了这个用户，你就可以轻松的开始阅读任任意的开源工程！\\n\\n\\n\\n## 下载AtomCode\\n\\n打开AtomCode官网下载[AtomCode](https://atomcode.atomgit.com/invite/NTDZZSH4)。\\n\\n![](assets/image-20260706222111692.png)\\n\\n---\\n\\n选择对应的操作系统进行下载安装\\n\\n![](assets/image-20260706222213006.png)\\n\\n打开终端，然后输入以下命令：\\n\\n```\\n$env:ATOMCODE_INVITE=\'NTDZZSH4\'; irm https://raw.atomgit.com/atomgit_atomcode/atomcode/raw/main/scripts/install.ps1 | iex\\n```\\n\\n![](assets/image-20260706222305619.png)\\n\\n## 首次启动\\n\\n待成功安装后，重启终端，然后输入 AtomCode 进行启动。\\n\\n> atomcode \\n\\n首次启动时，会让你选择语言、选择套餐（选择 **配置CodingPlan**）。进行基本的初始化后，就可以正常使用AtomCode了。\\n\\n![](assets/image-20260706222638079.png)\\n\\n## 下载要学习的源码\\n\\n因为AtomCode是开源，那这里就使用**AtomCode**客户端去学习开源的**AtomCode**工程，去了解这个AI 终端是如何构成的。\\n\\n打开AtomCode仓库地址\\n\\n```\\nhttps://atomgit.com/atomgit_atomcode/atomcode\\n```\\n\\n使用git下载到本地电脑任意位置\\n\\n```\\ngit clone https://atomgit.com/atomgit_atomcode/atomcode.git\\n```\\n\\n![](assets/image-20260706222733246.png)\\n\\n---\\n\\n![](assets/image-20260706222801051.png)\\n\\n## 在源码工程中打开AtomCode\\n\\n在源码工程中打开终端，然后启动AtomCode，这里为了减少AtomCode因为向用户请求授权中经常暂停任务，选择 授权完全权限的方式来启动AtomCode。\\n\\n```\\natomcode -y\\n```\\n\\n![](assets/image-20260706222956780.png)\\n\\n\\n\\n## 切换到Plan模式\\n\\n在执行任务时，如果你认为当前任务是复杂任务，那么建议先切换成Plan 计划模式，让AtomCode根据你的需求先指定计划，待你同意后，再去执行。在打开的AtomCode终端中，输入 `/Plan` 然后确定，便接入了计划模式。\\n\\n![](assets/image-20260706223601227.png)\\n\\n\\n\\n\\n\\n\\n\\n## 输入提示词 生成源码博客\\n\\n```\\n基于当前工程的源码，帮我生成一份wiki，格式我需要使用 vitepress，生成的md文章中，如果碰到专业的英语单词，我需要\\n| 实现鼠标移入时，弹出单词的音标、和介绍，另外碰到专业的技术名词也是一样，需要弹出解析方便阅读。\\n```\\n\\n---\\n\\nAtomCode等待片刻，会得出一份计划方案待用户审阅。\\n\\n![](assets/image-20260706223701770.png)\\n\\n---\\n\\n最后会请求你的确认，如果你确认了，便表示AtomCode得到授权。\\n\\n![](assets/image-20260706223758410.png)\\n\\n---\\n\\n需要注意的是，我们需要手动的由计划模式重新调整回Build模式（默认就是Build），输入 `/Build` 回车便可切换。\\n\\n---\\n\\n![](assets/image-20260706223942865.png)\\n\\n---\\n\\n然后主动对话，通知AtomCode 开始执行任务。\\n\\n```\\n开始吧\\n```\\n\\n接着AtomCode便开始执行任务，直到得到产物。\\n\\n![](assets/image-20260706224235790.png)\\n\\n---\\n\\n此时，我们可以直接让AtomCode帮我们把博客运行起来。\\n\\n```\\n帮我在本地运行，让我预览\\n```\\n\\nAtomCode会执行任务。\\n\\n![](assets/image-20260706224318689.png)\\n\\n---\\n\\n最后得到结果。\\n\\n![](assets/image-20260706224339445.png)\\n\\n---\\n\\n## 预览产物\\n\\n最后，在浏览器中打开上述地址，便可以得到AtomCode开源工程的阅读文档！。\\n\\n![](assets/image-20260706224552181.png)\\n\\n---\\n\\n---\\n\\n专业术语，有弹出窗口的提示。\\n\\n![](assets/image-20260706224614075.png)"}'),k={name:"AI人工智能/AtomCode 解读任意开源工程/AtomCode 解读任意开源工程.md"};function P(q,a,x,f,w,y){return e(),s("div",null,[...a[0]||(a[0]=[t("",66)])])}const T=n(k,[["render",P]]);export{D as __pageData,T as default};
